"use client";

import type * as React from "react";
import { useContext } from "react";
import { RenderStylesContext } from "./render-styles.internal";
import * as stylex from "@stylexjs/stylex";
import {
  composeRenderProps,
  Button as ButtonPrimitive,
  Link as LinkPrimitive,
  type ButtonProps as PrimitiveProps,
  type LinkProps,
} from "react-aria-components";

export type ButtonVariant =
  "default" | "outline" | "secondary" | "ghost" | "destructive" | "link";
export type ButtonSize =
  "default" | "xs" | "sm" | "lg" | "icon" | "icon-xs" | "icon-sm" | "icon-lg";
type Variants = {
  variant?: ButtonVariant | null;
  size?: ButtonSize | null;
  xstyle?: stylex.StyleXStyles;
};
type NoExternalClasses = { className?: never };
export type ButtonProps = Omit<PrimitiveProps, "className"> &
  React.RefAttributes<HTMLButtonElement> &
  Variants &
  NoExternalClasses;

// Expose the same resolved styles used by Button/LinkButton for other elements.
export function buttonProps({
  variant = "default",
  size = "default",
  xstyle,
  style,
}: Variants & { style?: React.CSSProperties } = {}) {
  const props = stylex.props(
    styles.base,
    variant && variants[variant],
    size && sizes[size],
    xstyle,
  );
  // Internal marker supports opaque descendant SVGs; it is not a customization API.
  return {
    className: ["ariax-button", props.className].filter(Boolean).join(" "),
    style: { ...props.style, ...style },
  };
}

export function Button({
  className: _className,
  style,
  xstyle,
  variant = "default",
  size = "default",
  ...props
}: ButtonProps) {
  const renderStyles = useContext(RenderStylesContext);
  const applied = buttonProps({
    variant,
    size,
    xstyle: [renderStyles, xstyle],
  });
  const button = (
    <ButtonPrimitive
      data-slot="button"
      data-variant={variant}
      data-size={size}
      {...props}
      {...applied}
      style={composeRenderProps(style, (value) => ({
        ...applied.style,
        ...value,
      }))}
    />
  );
  return renderStyles ? (
    <RenderStylesContext.Provider value={undefined}>
      {button}
    </RenderStylesContext.Provider>
  ) : (
    button
  );
}

export function LinkButton({
  className: _className,
  style,
  xstyle,
  variant = "default",
  size = "default",
  ...props
}: Omit<LinkProps, "className"> & Variants & NoExternalClasses) {
  const renderStyles = useContext(RenderStylesContext);
  const applied = buttonProps({
    variant,
    size,
    xstyle: [renderStyles, xstyle],
  });
  const button = (
    <LinkPrimitive
      data-slot="button"
      data-variant={variant}
      data-size={size}
      {...props}
      {...applied}
      style={composeRenderProps(style, (value) => ({
        ...applied.style,
        ...value,
      }))}
    />
  );
  return renderStyles ? (
    <RenderStylesContext.Provider value={undefined}>
      {button}
    </RenderStylesContext.Provider>
  ) : (
    button
  );
}

const styles = stylex.create({
  base: {
    display: "inline-flex",
    flexShrink: 0,
    alignItems: "center",
    justifyContent: "center",
    whiteSpace: "nowrap",
    userSelect: "none",
    outlineStyle: "none",
    transitionProperty: "all",
    transitionTimingFunction: "cubic-bezier(0.4, 0, 0.2, 1)",
    transitionDuration: "150ms",
    pointerEvents: { default: null, ":disabled": "none" },
    opacity: { default: null, ":disabled": 0.5 },
    borderRadius: "var(--radius)",
    borderWidth: 1,
    borderStyle: "solid",
    borderColor: {
      default: "transparent",
      ":focus-visible": "var(--ring)",
      ':is([aria-invalid="true"])': "var(--destructive)",
      ':is(.dark *)[aria-invalid="true"]':
        "color-mix(in oklab, var(--destructive) 50%, transparent)",
    },
    backgroundClip: "padding-box",
    fontSize: "0.875rem",
    lineHeight: "calc(1.25 / .875)",
    fontWeight: 500,
    "--ariax-ring": {
      default: "color-mix(in oklab, var(--ring) 50%, transparent)",
      ':is([aria-invalid="true"])':
        "color-mix(in oklab, var(--destructive) 20%, transparent)",
      ':is(.dark *)[aria-invalid="true"]':
        "color-mix(in oklab, var(--destructive) 40%, transparent)",
    },
    boxShadow: {
      default: null,
      ":focus-visible":
        "0 0 0 0 #0000, 0 0 0 0 #0000, 0 0 0 0 #0000, 0 0 0 3px var(--ariax-ring), 0 0 0 0 #0000",
      ':is([aria-invalid="true"])':
        "0 0 0 0 #0000, 0 0 0 0 #0000, 0 0 0 0 #0000, 0 0 0 3px var(--ariax-ring), 0 0 0 0 #0000",
    },
    translate: { default: null, ":active:not([aria-haspopup])": "0 1px" },
    "--ariax-icon-size": "calc(var(--ariax-spacing, .25rem) * 4)",
  },
});

const variants = stylex.create({
  default: {
    backgroundColor: {
      default: "var(--primary)",
      ":hover": {
        default: null,
        "@media (hover: hover)":
          "color-mix(in oklab, var(--primary) 80%, transparent)",
      },
    },
    color: "var(--primary-foreground)",
  },
  outline: {
    borderColor: {
      default: "var(--border)",
      ":is(.dark *)": "var(--input)",
      ":focus-visible": "var(--ring)",
      ":is(.dark *):focus-visible": "var(--input)",
      ':is([aria-invalid="true"])': "var(--destructive)",
      ':is(.dark *)[aria-invalid="true"]':
        "color-mix(in oklab, var(--destructive) 50%, transparent)",
    },
    backgroundColor: {
      default: "var(--background)",
      ":hover": { default: null, "@media (hover: hover)": "var(--muted)" },
      ':is([aria-expanded="true"])': "var(--muted)",
      ":is(.dark *)": "color-mix(in oklab, var(--input) 30%, transparent)",
      ':is(.dark *)[aria-expanded="true"]':
        "color-mix(in oklab, var(--input) 30%, transparent)",
      ":is(.dark *):hover": {
        default: null,
        "@media (hover: hover)":
          "color-mix(in oklab, var(--input) 50%, transparent)",
      },
    },
    color: {
      default: null,
      ":hover": { default: null, "@media (hover: hover)": "var(--foreground)" },
      ':is([aria-expanded="true"])': "var(--foreground)",
    },
  },
  secondary: {
    backgroundColor: {
      default: "var(--secondary)",
      ":hover": {
        default: null,
        "@media (hover: hover)":
          "color-mix(in oklch, var(--secondary), var(--foreground) 5%)",
      },
      ':is([aria-expanded="true"])': "var(--secondary)",
    },
    color: "var(--secondary-foreground)",
  },
  ghost: {
    backgroundColor: {
      default: null,
      ":hover": { default: null, "@media (hover: hover)": "var(--muted)" },
      ':is([aria-expanded="true"])': "var(--muted)",
      ":is(.dark *):hover": {
        default: null,
        "@media (hover: hover)":
          "color-mix(in oklab, var(--muted) 50%, transparent)",
      },
    },
    color: {
      default: null,
      ":hover": { default: null, "@media (hover: hover)": "var(--foreground)" },
      ':is([aria-expanded="true"])': "var(--foreground)",
    },
  },
  destructive: {
    backgroundColor: {
      default: "color-mix(in oklab, var(--destructive) 10%, transparent)",
      ":hover": {
        default: null,
        "@media (hover: hover)":
          "color-mix(in oklab, var(--destructive) 20%, transparent)",
      },
      ":is(.dark *)":
        "color-mix(in oklab, var(--destructive) 20%, transparent)",
      ":is(.dark *):hover": {
        default: null,
        "@media (hover: hover)":
          "color-mix(in oklab, var(--destructive) 30%, transparent)",
      },
    },
    color: "var(--destructive)",
    "--ariax-ring": {
      default: "color-mix(in oklab, var(--destructive) 20%, transparent)",
      ":is(.dark *)":
        "color-mix(in oklab, var(--destructive) 40%, transparent)",
    },
    borderColor: {
      default: "transparent",
      ":focus-visible":
        "color-mix(in oklab, var(--destructive) 40%, transparent)",
      ':is([aria-invalid="true"])': "var(--destructive)",
      ':is(.dark *)[aria-invalid="true"]':
        "color-mix(in oklab, var(--destructive) 50%, transparent)",
    },
  },
  link: {
    color: "var(--primary)",
    textUnderlineOffset: 4,
    textDecorationLine: {
      default: null,
      ":hover": { default: null, "@media (hover: hover)": "underline" },
    },
  },
});

const sizes = stylex.create({
  default: {
    height: "calc(var(--ariax-spacing, .25rem) * 8)",
    gap: "calc(var(--ariax-spacing, .25rem) * 1.5)",
    paddingInline: "calc(var(--ariax-spacing, .25rem) * 2.5)",
    paddingInlineEnd: {
      default: "calc(var(--ariax-spacing, .25rem) * 2.5)",
      ':has([data-icon="inline-end"])':
        "calc(var(--ariax-spacing, .25rem) * 2)",
    },
    paddingInlineStart: {
      default: "calc(var(--ariax-spacing, .25rem) * 2.5)",
      ':has([data-icon="inline-start"])':
        "calc(var(--ariax-spacing, .25rem) * 2)",
    },
  },
  xs: {
    height: "calc(var(--ariax-spacing, .25rem) * 6)",
    gap: "calc(var(--ariax-spacing, .25rem) * 1)",
    borderRadius: {
      default: "min(calc(var(--radius) * 0.8), 10px)",
      ':is([data-slot="button-group"] *)': "var(--radius)",
    },
    paddingInline: "calc(var(--ariax-spacing, .25rem) * 2)",
    paddingInlineEnd: {
      default: "calc(var(--ariax-spacing, .25rem) * 2)",
      ':has([data-icon="inline-end"])':
        "calc(var(--ariax-spacing, .25rem) * 1.5)",
    },
    paddingInlineStart: {
      default: "calc(var(--ariax-spacing, .25rem) * 2)",
      ':has([data-icon="inline-start"])':
        "calc(var(--ariax-spacing, .25rem) * 1.5)",
    },
    fontSize: "0.75rem",
    lineHeight: "calc(1 / .75)",
    "--ariax-icon-size": "calc(var(--ariax-spacing, .25rem) * 3)",
  },
  sm: {
    height: "calc(var(--ariax-spacing, .25rem) * 7)",
    gap: "calc(var(--ariax-spacing, .25rem) * 1)",
    borderRadius: {
      default: "min(calc(var(--radius) * 0.8), 12px)",
      ':is([data-slot="button-group"] *)': "var(--radius)",
    },
    paddingInline: "calc(var(--ariax-spacing, .25rem) * 2.5)",
    paddingInlineEnd: {
      default: "calc(var(--ariax-spacing, .25rem) * 2.5)",
      ':has([data-icon="inline-end"])':
        "calc(var(--ariax-spacing, .25rem) * 1.5)",
    },
    paddingInlineStart: {
      default: "calc(var(--ariax-spacing, .25rem) * 2.5)",
      ':has([data-icon="inline-start"])':
        "calc(var(--ariax-spacing, .25rem) * 1.5)",
    },
    fontSize: "0.8rem",
    lineHeight: "inherit",
    "--ariax-icon-size": "calc(var(--ariax-spacing, .25rem) * 3.5)",
  },
  lg: {
    height: "calc(var(--ariax-spacing, .25rem) * 9)",
    gap: "calc(var(--ariax-spacing, .25rem) * 1.5)",
    paddingInline: "calc(var(--ariax-spacing, .25rem) * 2.5)",
    paddingInlineEnd: {
      default: "calc(var(--ariax-spacing, .25rem) * 2.5)",
      ':has([data-icon="inline-end"])':
        "calc(var(--ariax-spacing, .25rem) * 2)",
    },
    paddingInlineStart: {
      default: "calc(var(--ariax-spacing, .25rem) * 2.5)",
      ':has([data-icon="inline-start"])':
        "calc(var(--ariax-spacing, .25rem) * 2)",
    },
  },
  icon: {
    width: "calc(var(--ariax-spacing, .25rem) * 8)",
    height: "calc(var(--ariax-spacing, .25rem) * 8)",
  },
  "icon-xs": {
    width: "calc(var(--ariax-spacing, .25rem) * 6)",
    height: "calc(var(--ariax-spacing, .25rem) * 6)",
    borderRadius: {
      default: "min(calc(var(--radius) * 0.8), 10px)",
      ':is([data-slot="button-group"] *)': "var(--radius)",
    },
    "--ariax-icon-size": "calc(var(--ariax-spacing, .25rem) * 3)",
  },
  "icon-sm": {
    width: "calc(var(--ariax-spacing, .25rem) * 7)",
    height: "calc(var(--ariax-spacing, .25rem) * 7)",
    borderRadius: {
      default: "min(calc(var(--radius) * 0.8), 12px)",
      ':is([data-slot="button-group"] *)': "var(--radius)",
    },
  },
  "icon-lg": {
    width: "calc(var(--ariax-spacing, .25rem) * 9)",
    height: "calc(var(--ariax-spacing, .25rem) * 9)",
  },
});

"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { ArrowDownIcon } from "lucide-react";
import {
  MessageScroller as Primitive,
  useMessageScroller,
  useMessageScrollerScrollable,
  useMessageScrollerVisibility,
} from "@shadcn/react/message-scroller";
import { Button, type ButtonProps } from "./button";
import { RenderStylesContext } from "./render-styles.internal";
type Styled<P> = Omit<P, "className"> & {
  className?: never;
  xstyle?: stylex.StyleXStyles;
};
export function MessageScrollerProvider(
  props: React.ComponentProps<typeof Primitive.Provider>,
) {
  return <Primitive.Provider {...props} />;
}
export function MessageScroller({
  className: _,
  xstyle,
  style,
  ...props
}: Styled<React.ComponentProps<typeof Primitive.Root>>) {
  const sx = stylex.props(styles.root, xstyle);
  return (
    <Primitive.Root
      data-slot="message-scroller"
      {...props}
      className={sx.className}
      style={{
        ...sx.style,
        ...style,
      }}
    />
  );
}
export function MessageScrollerViewport({
  className: _,
  xstyle,
  style,
  ...props
}: Styled<React.ComponentProps<typeof Primitive.Viewport>>) {
  const sx = stylex.props(styles.viewport, xstyle);
  return (
    <Primitive.Viewport
      data-slot="message-scroller-viewport"
      {...props}
      className={sx.className}
      style={{
        ...sx.style,
        ...style,
      }}
    />
  );
}
export function MessageScrollerContent({
  className: _,
  spacerClassName: _spacer,
  xstyle,
  style,
  ...props
}: Styled<
  Omit<React.ComponentProps<typeof Primitive.Content>, "spacerClassName">
> & {
  spacerClassName?: never;
}) {
  const sx = stylex.props(styles.content, xstyle);
  return (
    <Primitive.Content
      data-slot="message-scroller-content"
      {...props}
      className={sx.className}
      style={{
        ...sx.style,
        ...style,
      }}
    />
  );
}
export function MessageScrollerItem({
  className: _,
  xstyle,
  style,
  scrollAnchor = false,
  ...props
}: Styled<React.ComponentProps<typeof Primitive.Item>>) {
  const sx = stylex.props(styles.item, xstyle);
  return (
    <Primitive.Item
      data-slot="message-scroller-item"
      scrollAnchor={scrollAnchor}
      {...props}
      className={sx.className}
      style={{
        ...sx.style,
        ...style,
      }}
    />
  );
}
export type MessageScrollerButtonProps = Styled<
  React.ComponentProps<typeof Primitive.Button>
> &
  Pick<ButtonProps, "variant" | "size">;
export function MessageScrollerButton({
  className: _,
  xstyle,
  style,
  direction = "end",
  variant = "secondary",
  size = "icon-sm",
  render,
  children,
  ...props
}: MessageScrollerButtonProps) {
  const sr = stylex.props(styles.srOnly);
  const applied = [styles.button, xstyle];
  const sx = stylex.props(applied);
  return (
    <RenderStylesContext.Provider value={applied}>
      <Primitive.Button
        data-slot="message-scroller-button"
        data-direction={direction}
        data-variant={variant}
        data-size={size}
        direction={direction}
        {...props}
        className={sx.className}
        style={{
          ...sx.style,
          ...style,
        }}
        render={render ?? <Button variant={variant} size={size} />}
      >
        {children ?? (
          <>
            <ArrowDownIcon />
            <span className={sr.className} style={sr.style}>
              {direction === "end" ? "Scroll to end" : "Scroll to start"}
            </span>
          </>
        )}
      </Primitive.Button>
    </RenderStylesContext.Provider>
  );
}
export {
  useMessageScroller,
  useMessageScrollerScrollable,
  useMessageScrollerVisibility,
};
// shadcn 4.21.1 scroll-fade (MIT); SHADCN-LICENSE is installed with the styles.
const fade = stylex.keyframes({
  from: {
    // @ts-expect-error StyleX supports registered CSS properties; keyframe types omit them.
    "--scroll-fade-b":
      "var(--_scroll-fade-size-b,var(--scroll-fade-size,min(12%,calc(var(--ariax-spacing, .25rem) * 10))))",
  },
  to: {
    // @ts-expect-error Registered CSS property.
    "--scroll-fade-b": "0px",
  },
});
const styles = stylex.create({
  root: {
    position: "relative",
    display: "flex",
    width: "100%",
    height: "100%",
    minHeight: 0,
    flexDirection: "column",
    overflow: "hidden",
  },
  viewport: {
    width: "100%",
    height: "100%",
    minHeight: 0,
    minWidth: 0,
    overflowY: "auto",
    scrollbarWidth: "thin",
    scrollbarGutter: "stable",
    overscrollBehavior: "contain",
    contain: "content",
    visibility: {
      default: null,
      ":is([data-pending-scroll])": "hidden",
    },
    scrollbarColor: {
      default: null,
      ":is([data-autoscrolling])": "transparent transparent",
    },
    "--_scroll-fade-size-b":
      "var(--scroll-fade-b-size,var(--scroll-fade-size,min(12%,calc(var(--ariax-spacing, .25rem) * 10))))",
    "--scroll-fade-mask":
      "linear-gradient(to bottom,#000 0,#000 calc(100% - var(--scroll-fade-b,0px)),transparent 100%)",
    WebkitMaskImage: "var(--scroll-fade-mask)",
    maskImage: "var(--scroll-fade-mask)",
    WebkitMaskComposite: {
      default: null,
      "@supports not (mask-composite: intersect)": "source-in",
    },
    maskComposite: "intersect",
    WebkitMaskRepeat: "no-repeat",
    maskRepeat: "no-repeat",
    animationName: {
      default: null,
      "@supports (animation-timeline: scroll())": fade,
    },
    animationDuration: {
      default: null,
      "@supports (animation-timeline: scroll())": "1ms",
    },
    animationTimingFunction: {
      default: null,
      "@supports (animation-timeline: scroll())": "ease-in-out",
    },
    animationTimeline: {
      default: null,
      "@supports (animation-timeline: scroll())": "scroll(self y)",
    },
    animationRange: {
      default: null,
      "@supports (animation-timeline: scroll())":
        "calc(100% - var(--scroll-fade-reveal,calc(var(--ariax-spacing, .25rem) * 24))) 100%",
    },
    animationFillMode: {
      default: null,
      "@supports (animation-timeline: scroll())": "both",
    },
    "--scroll-fade-b": {
      default: null,
      "@supports not (animation-timeline: scroll())":
        "var(--_scroll-fade-size-b)",
    },
  },
  content: {
    gap: "calc(var(--ariax-spacing, .25rem) * 6)",
    display: "flex",
    height: "max-content",
    minHeight: "100%",
    flexDirection: "column",
  },
  item: {
    minWidth: 0,
    flexShrink: 0,
    containIntrinsicSize: "auto 10rem",
    contentVisibility: "auto",
  },
  button: {
    position: "absolute",
    insetInlineStart: "50%",
    translate: {
      default: "-50% 0",
      ':is([dir="rtl"] *)': "50% 0",
      ':is([data-active="false"][data-direction="end"])': "-50% 100%",
      ':is([data-active="false"][data-direction="start"])': "-50% -100%",
      ':is([dir="rtl"] *)[data-active="false"][data-direction="end"]':
        "50% 100%",
      ':is([dir="rtl"] *)[data-active="false"][data-direction="start"]':
        "50% -100%",
    },
    borderColor: "var(--border)",
    backgroundColor: {
      default: "var(--background)",
      ":hover": {
        default: null,
        "@media (hover: hover)": "var(--muted)",
      },
    },
    color: "var(--foreground)",
    transitionProperty: "translate,scale,opacity",
    transitionDuration: {
      default: "200ms",
      ':is([data-active="false"])': "400ms",
    },
    transitionTimingFunction: {
      default: "cubic-bezier(0.4,0,0.2,1)",
      ':is([data-active="true"])': "cubic-bezier(0.23,1,0.32,1)",
      ':is([data-active="false"])': "cubic-bezier(0.7,0,0.84,0)",
    },
    pointerEvents: {
      default: null,
      ':is([data-active="false"])': "none",
    },
    scale: {
      default: null,
      ':is([data-active="false"])': ".95",
      ':is([data-active="true"])': "1",
    },
    opacity: {
      default: null,
      ':is([data-active="false"])': 0,
      ':is([data-active="true"])': 1,
    },
    bottom: {
      default: null,
      ':is([data-direction="end"])': "calc(var(--ariax-spacing, .25rem) * 4)",
    },
    top: {
      default: null,
      ':is([data-direction="start"])': "calc(var(--ariax-spacing, .25rem) * 4)",
    },
  },
  srOnly: {
    position: "absolute",
    width: 1,
    height: 1,
    padding: 0,
    margin: -1,
    overflow: "hidden",
    clipPath: "inset(50%)",
    whiteSpace: "nowrap",
    borderWidth: 0,
  },
});

import { createContext } from "react";
import type { StyleXStyles } from "@stylexjs/stylex";
// Primitive render elements receive internal styles without opening the className API.
export const RenderStylesContext = createContext<StyleXStyles | undefined>(
  undefined,
);

import * as stylex from "@stylexjs/stylex";

// tw-animate-css 1.4.0 (MIT); see the distributed TW-ANIMATE-LICENSE.
const enter = stylex.keyframes({
  from: {
    opacity: "var(--ariax-enter-opacity, 1)",
    transform:
      "translate3d(var(--ariax-enter-x, 0), var(--ariax-enter-y, 0), 0) scale3d(var(--ariax-enter-scale, 1), var(--ariax-enter-scale, 1), var(--ariax-enter-scale, 1)) rotate(0)",
    filter: "blur(0)",
  },
});
const exit = stylex.keyframes({
  to: {
    opacity: "var(--ariax-exit-opacity, 1)",
    transform:
      "translate3d(0, 0, 0) scale3d(var(--ariax-exit-scale, 1), var(--ariax-exit-scale, 1), var(--ariax-exit-scale, 1)) rotate(0)",
    filter: "blur(0)",
  },
});
const pulse = stylex.keyframes({ "50%": { opacity: 0.5 } });
const spin = stylex.keyframes({ to: { transform: "rotate(360deg)" } });

// shadcn 4.21.1 scroll-fade (MIT); SHADCN-LICENSE is distributed by the registry.
const scrollRevealTop = stylex.keyframes({
  // @ts-expect-error StyleX keyframes accepts registered CSS properties; its type omits them.
  from: { "--scroll-fade-t": "0px" },
  to: {
