::placeholder {
  opacity: 1;
}

/*
  Set the default placeholder color to a semi-transparent version of the current text color in browsers that do not
  crash when using `color-mix(…)` with `currentcolor`. (https://github.com/tailwindlabs/tailwindcss/issues/17194)
*/

@supports (not (-webkit-appearance: -apple-pay-button)) /* Not Safari */ or
  (contain-intrinsic-size: 1px) /* Safari 17+ */ {
  ::placeholder {
    color: color-mix(in oklab, currentcolor 50%, transparent);
  }
}

/*
  Prevent resizing textareas horizontally by default.
*/

textarea {
  resize: vertical;
}

/*
  Remove the inner padding in Chrome and Safari on macOS.
*/

::-webkit-search-decoration {
  -webkit-appearance: none;
}

/*
  1. Ensure date/time inputs have the same height when empty in iOS Safari.
  2. Ensure text alignment can be changed on date/time inputs in iOS Safari.
*/

::-webkit-date-and-time-value {
  min-height: 1lh; /* 1 */
  text-align: inherit; /* 2 */
}

/*
  Prevent height from changing on date/time inputs in macOS Safari when the input is set to `display: block`.
*/

::-webkit-datetime-edit {
  display: inline-flex;
}

/*
  Remove excess padding from pseudo-elements in date/time inputs to ensure consistent height across browsers.
*/

::-webkit-datetime-edit-fields-wrapper {
  padding: 0;
}

::-webkit-datetime-edit,
::-webkit-datetime-edit-year-field,
::-webkit-datetime-edit-month-field,
::-webkit-datetime-edit-day-field,
::-webkit-datetime-edit-hour-field,
::-webkit-datetime-edit-minute-field,
::-webkit-datetime-edit-second-field,
::-webkit-datetime-edit-millisecond-field,
::-webkit-datetime-edit-meridiem-field {
  padding-block: 0;
}

/*
  Center dropdown marker shown on inputs with paired `<datalist>`s in Chrome. (https://github.com/tailwindlabs/tailwindcss/issues/18499)
*/

::-webkit-calendar-picker-indicator {
  line-height: 1;
}

/*
  Remove the additional `:invalid` styles in Firefox. (https://github.com/mozilla/gecko-dev/blob/2f9eacd9d3d995c937b4251a5557d95d494c9be1/layout/style/res/forms.css#L728-L737)
*/

:-moz-ui-invalid {
  box-shadow: none;
}

/*
  Correct the inability to style the border radius in iOS Safari.
*/

button,
input:where([type="button"], [type="reset"], [type="submit"]),
::file-selector-button {
  appearance: button;
}

/*
  Correct the cursor style of increment and decrement buttons in Safari.
*/

::-webkit-inner-spin-button,
::-webkit-outer-spin-button {
  height: auto;
}

/*
  Make elements with the HTML hidden attribute stay hidden by default.
*/

[hidden]:where(:not([hidden="until-found"])) {
  display: none !important;
}

.ariax-resizable-handle::after {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline-start: var(--ariax-resizable-after-start);
  width: var(--ariax-resizable-after-width);
  height: var(--ariax-resizable-after-height);
  translate: var(--ariax-resizable-after-translate);
}

@property --ariax-select-width {
  syntax: "*";
  inherits: false;
  initial-value: fit-content;
}
.ariax-select-trigger [data-slot="select-value"] {
  overflow: hidden;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  display: flex;
  align-items: center;
  gap: calc(var(--ariax-spacing, 0.25rem) * 1.5);
}
.ariax-select-trigger svg,
.ariax-select-item svg {
  pointer-events: none;
  flex-shrink: 0;
}
.ariax-select-trigger svg:not([class*="size-"]),
.ariax-select-item svg:not([class*="size-"]) {
  width: calc(var(--ariax-spacing, 0.25rem) * 4);
  height: calc(var(--ariax-spacing, 0.25rem) * 4);
}
.ariax-select-item:not(#\#):not(#\#):not(#\#):not(
    [data-variant="destructive"]
  ):focus
  * {
  color: var(--accent-foreground);
}
.ariax-select-item > span:last-child {
  gap: calc(var(--ariax-spacing, 0.25rem) * 2);
}
/* Field's child-width contract must outrank the Select fit-content default. */
.ariax-field[data-orientation="vertical"] > [data-slot="select"],
.ariax-field[data-orientation="responsive"] > [data-slot="select"] {
  --ariax-select-width: var(--ariax-field-full);
}
@container field-group (min-width: 28rem) {
  .ariax-field[data-orientation="responsive"] > [data-slot="select"] {
    --ariax-select-width: var(--ariax-field-auto);
  }
}

[data-sidebar="group-label"] > svg,
.ariax-sidebar-group-label > svg,
.ariax-sidebar-group-action > svg,
.ariax-sidebar-menu-button svg,
.ariax-sidebar-menu-action > svg,
.ariax-sidebar-menu-sub-button > svg {
  width: calc(var(--ariax-spacing, 0.25rem) * 4);
  height: calc(var(--ariax-spacing, 0.25rem) * 4);
  flex-shrink: 0;
}
.ariax-sidebar-menu-sub-button > svg {
  color: var(--sidebar-accent-foreground);
}
.ariax-sidebar-menu-button > span:last-child,
.ariax-sidebar-menu-sub-button > span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
[data-mobile="true"] [data-slot="sheet-content"] > button {
  display: none;
}

/* RAC creates header rows internally, without the exported TableRow wrapper. */
.ariax-table-header tr {
  border-bottom-width: var(--ariax-table-header-border, 1px);
}
.ariax-table-body tr:last-child {
  --ariax-table-row-border: 0px;
}
.ariax-table-footer:last-child > tr {
  --ariax-table-row-border: 0px;
}

.ariax-tabs-trigger svg {
  pointer-events: none;
  flex-shrink: 0;
}
.ariax-tabs-trigger svg:not([class*="size-"]) {
  width: calc(var(--ariax-spacing, 0.25rem) * 4);
  height: calc(var(--ariax-spacing, 0.25rem) * 4);
}
.ariax-tabs-trigger:has([data-icon="inline-start"]) {
  padding-inline-start: calc(var(--ariax-spacing, 0.25rem) * 1);
}
.ariax-tabs-trigger:has([data-icon="inline-end"]) {
  padding-inline-end: calc(var(--ariax-spacing, 0.25rem) * 1);
}

